using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text.Json;
using Jindan.Contracts;
using Jindan.Core;
using static Jindan.Core.DomainRules;
namespace Jindan.Infrastructure;

public sealed partial class LocalWorkspace : IWorkspaceData, IIdentityService, IAssetService, ILayoutStore, IDisposable
{
    readonly string _root, _file, _backup, _assets; readonly SemaphoreSlim _gate = new(1, 1); readonly ConcurrentDictionary<string, RecordSchema> _schemas = new(StringComparer.Ordinal); readonly Dictionary<Identity, string> _sessions = new(ReferenceEqualityComparer.Instance); State _state; bool _disposed;
    static readonly JsonSerializerOptions Json = new() { WriteIndented = true, PropertyNameCaseInsensitive = false };
    public string DataRoot => _root;
    public bool RecoveredFromBackup { get; private set; }
    public LocalWorkspace(string dataRoot) { Require(Path.IsPathFullyQualified(dataRoot), "PATH", "An absolute new local workspace path is required."); _root = Path.GetFullPath(dataRoot).TrimEnd(Path.DirectorySeparatorChar); var protectedRoot = Path.GetFullPath("F:/jindan").TrimEnd(Path.DirectorySeparatorChar); Require(!_root.Equals(protectedRoot, StringComparison.OrdinalIgnoreCase) && !_root.StartsWith(protectedRoot + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase), "PROTECTED_ROOT", "The preserved legacy workspace cannot be used as a data store."); var maintenance = Path.GetFullPath("F:/jindan-maintenance").TrimEnd(Path.DirectorySeparatorChar); Require(!_root.Equals(maintenance, StringComparison.OrdinalIgnoreCase) && !_root.StartsWith(maintenance + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase), "PROTECTED_ROOT", "Maintenance evidence cannot be used as a data store."); CheckNoLinks(_root); Directory.CreateDirectory(_root); _file = Path.Combine(_root, "workspace.json"); _backup = _file + ".bak"; _assets = Path.Combine(_root, "assets"); CheckNoLinks(_assets); Directory.CreateDirectory(_assets); _state = ReadState(); }
    static void CheckNoLinks(string path) { for (var current = new DirectoryInfo(path); current is not null; current = current.Parent) if (current.Exists) Require((current.Attributes & FileAttributes.ReparsePoint) == 0, "PATH", "Reparse-point workspaces are not allowed."); }
    State ReadState() { if (!File.Exists(_file)) return new(); try { return ReadStateFile(_file); } catch (WorkspaceException) { throw; } catch (Exception e) when (e is JsonException or InvalidDataException) { if (!File.Exists(_backup)) throw new WorkspaceException("CORRUPT_STORE", "The local store is corrupt and has no valid backup."); State restored; try { restored = ReadStateFile(_backup); } catch { throw new WorkspaceException("CORRUPT_STORE", "The local store and backup require independent recovery."); } File.Copy(_file, Path.Combine(_root, $"workspace.corrupt-{Guid.NewGuid():N}.json")); AtomicBytes(_file, File.ReadAllBytes(_backup), null); RecoveredFromBackup = true; return restored; } }
    static State ReadStateFile(string path) { Require((File.GetAttributes(path) & FileAttributes.ReparsePoint) == 0, "PATH", "Linked data files are not allowed."); Require(new FileInfo(path).Length <= 64 * 1024 * 1024, "STORE_LIMIT", "Local store is too large."); var value = JsonSerializer.Deserialize<State>(File.ReadAllBytes(path), Json) ?? throw new InvalidDataException(); Require(value.SchemaVersion == Contract.DataSchema, "SCHEMA_FUTURE", "Unsupported data schema; no automatic downgrade is allowed."); if (value.Users is null || value.Records is null || value.Assets is null || value.Layout is null || value.Users.Any(u => u is null || string.IsNullOrWhiteSpace(u.Id) || string.IsNullOrWhiteSpace(u.DisplayName) || u.Role is not ("admin" or "editor" or "viewer") || u.ProjectIds is null || u.Position is null || u.Position.Length > 100) || value.Records.Any(r => r is null || string.IsNullOrWhiteSpace(r.Id) || r.Fields is null) || value.Assets.Any(a => a is null || a.Sha256 is null || a.Sha256.Length != 64 || a.ProjectId is null) || value.Records.Select(r => r.Id).Distinct().Count() != value.Records.Count || value.Users.Select(u => u.Id).Distinct().Count() != value.Users.Count) throw new InvalidDataException(); return value; }
    static void AtomicBytes(string path, byte[] bytes, string? backup) { CheckNoLinks(Path.GetDirectoryName(path)!); if (File.Exists(path)) Require((File.GetAttributes(path) & FileAttributes.ReparsePoint) == 0, "PATH", "Linked data files are not allowed."); var temp = path + ".tmp-" + Guid.NewGuid().ToString("N"); try { using (var s = new FileStream(temp, FileMode.CreateNew, FileAccess.Write, FileShare.None)) { s.Write(bytes); s.Flush(true); } if (File.Exists(path)) { if (backup is null) File.Move(temp, path, true); else File.Replace(temp, path, backup, true); } else File.Move(temp, path); } finally { if (File.Exists(temp)) File.Delete(temp); } }
    State Clone() => JsonSerializer.Deserialize<State>(JsonSerializer.SerializeToUtf8Bytes(_state, Json), Json)!;
    void Commit(State next, CancellationToken ct) { ct.ThrowIfCancellationRequested(); next.Revision++; var bytes = JsonSerializer.SerializeToUtf8Bytes(next, Json); Require(bytes.Length <= 64 * 1024 * 1024, "STORE_LIMIT", "The local store exceeds64MiB; export and split the workspace before continuing."); AtomicBytes(_file, bytes, _backup); _state = next; }
    async Task<T> Locked<T>(Func<T> action, CancellationToken ct) { ObjectDisposedException.ThrowIf(_disposed, this); await _gate.WaitAsync(ct).ConfigureAwait(false); try { return await Task.Run(() => { ct.ThrowIfCancellationRequested(); using var lease = AcquireStoreLease(ct); if (File.Exists(_file)) _state = ReadStateFile(_file); else Require(_state.Revision == 0, "CORRUPT_STORE", "The active store disappeared."); return action(); }, ct).ConfigureAwait(false); } finally { _gate.Release(); } }
    FileStream AcquireStoreLease(CancellationToken ct) { var path = Path.Combine(_root, "workspace.lock"); var timer = System.Diagnostics.Stopwatch.StartNew(); while (true) { ct.ThrowIfCancellationRequested(); try { return new FileStream(path, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None); } catch (IOException) { Require(timer.Elapsed < TimeSpan.FromSeconds(10), "STORE_BUSY", "Another local workspace operation holds the store lock."); ct.WaitHandle.WaitOne(25); } } }
    StoredUser Actor(Identity actor) { Require(actor is not null && _sessions.TryGetValue(actor, out _), "UNAUTHENTICATED", "Log in to this local workspace."); var user = _state.Users.SingleOrDefault(u => u.Id == _sessions[actor]); Require(user is not null && !user.Disabled, "UNAUTHENTICATED", "This local user is unavailable."); return user!; }
    static void Admin(StoredUser user) => Require(user.Role == "admin", "FORBIDDEN", "A local administrator is required.");
    bool Readable(StoredUser user, WorkRecord record) { if (user.Role == "admin") return true; if (IsProject(record.Kind)) return user.ProjectIds.Contains(record.Id); if (record.ProjectId is not null) return user.ProjectIds.Contains(record.ProjectId) && _state.Records.Any(r => IsProject(r.Kind) && r.Id == record.ProjectId && !r.Deleted); return record.Kind == "board" || record.Kind == "tasks" && record.Fields.GetValueOrDefault("isPublic") == "true" || record.OwnerId == user.Id; }
    void Writable(StoredUser user, WorkRecord record) { Require(user.Role is "admin" or "editor", "FORBIDDEN", "The user cannot modify records."); Require(Readable(user, record), "FORBIDDEN", "This record is outside the authorized project or owner scope."); if (record.Kind is "board" or "tasks") Require(user.Role == "admin" || record.OwnerId == user.Id, "FORBIDDEN", "Only the owner or administrator can change this shared record."); }
    RecordSchema Schema(string kind) { Require(_schemas.TryGetValue(kind, out _), "SCHEMA_REQUIRED", "Register the record schema before using this kind."); return _schemas[kind]; }
    static WorkRecord Copy(WorkRecord record) => record with { Fields = new(record.Fields, StringComparer.Ordinal) };
    public void RegisterSchema(RecordSchema schema) { ValidateSchema(schema); var frozen = schema with { Fields = schema.Fields.Select(f => f with { Choices = f.Choices?.ToArray() }).ToArray() }; if (_schemas.TryGetValue(schema.Kind, out var previous)) Require(JsonSerializer.Serialize(previous, Json) == JsonSerializer.Serialize(frozen, Json), "SCHEMA_CONFLICT", "A different schema is already registered for this record kind."); else Require(_schemas.TryAdd(schema.Kind, frozen), "SCHEMA_CONFLICT", "Concurrent schema registration failed."); }
    public Task<IReadOnlyList<WorkRecord>> ListAsync(Identity actor, RecordQuery query, CancellationToken ct = default) => Locked<IReadOnlyList<WorkRecord>>(() => { var user = Actor(actor); Require(query.Kind is { Length: > 0 and <= 80 } && query.Kind.All(c => char.IsAsciiLetterOrDigit(c) || c is '-' or '_'), "SCHEMA", "Invalid query record kind."); Require(query.Search.Length <= 1000, "VALIDATION", "Search is too long."); if (query.ProjectId is not null) Require(user.Role == "admin" || user.ProjectIds.Contains(query.ProjectId), "FORBIDDEN", "The project is not assigned to this user."); return _state.Records.Where(r => r.Kind == query.Kind && (query.IncludeDeleted || !r.Deleted) && (query.ProjectId is null || r.ProjectId == query.ProjectId) && Readable(user, r) && (query.Search.Length == 0 || r.Fields.Values.Any(v => v.Contains(query.Search, StringComparison.OrdinalIgnoreCase)))).Select(Copy).ToArray(); }, ct);
    public Task<WorkRecord> SaveAsync(Identity actor, RecordDraft draft, CancellationToken ct = default) => Locked(() =>
    {
        var user = Actor(actor); var schema = Schema(draft.Kind); var fields = ValidateFields(schema, draft.Fields); WorkRecord? old = null; if (draft.Id is not null) { old = _state.Records.SingleOrDefault(r => r.Id == draft.Id && r.Kind == draft.Kind); Require(old is not null && !old.Deleted, "NOT_FOUND", "Record not found."); Writable(user, old!); Require(old!.Revision == draft.ExpectedRevision, "REVISION", "The record has changed. Reload it before saving."); Require(old.ProjectId == draft.ProjectId, "PROJECT_SCOPE", "A record cannot move between projects."); } else { Require(draft.ExpectedRevision == 0, "REVISION", "A new record must have revision zero."); Require(user.Role is "admin" or "editor", "FORBIDDEN", "This role cannot create records."); if (IsProject(draft.Kind)) Admin(user); }
        ValidateRelations(draft, fields, old, _state.Records); if (draft.Kind == "board") { var attachmentIds = AttachmentIds(fields); Require(attachmentIds.Length <= 10, "ATTACHMENT_LIMIT", "At most10 local attachments are allowed."); foreach (var attachmentId in attachmentIds) { var attachment = _state.Assets.SingleOrDefault(a => a.Id == attachmentId); Require(attachment is not null, "ASSET_NOT_FOUND", "The attachment does not exist."); AssetAccess(user, attachment!.ProjectId); } }
        if (schema.ProjectScoped) { Require(draft.ProjectId is not null, "PROJECT_SCOPE", "Select a project."); Require(_state.Records.Any(r => IsProject(r.Kind) && r.Id == draft.ProjectId && !r.Deleted), "PROJECT_SCOPE", "The parent project does not exist."); Require(user.Role == "admin" || user.ProjectIds.Contains(draft.ProjectId!), "FORBIDDEN", "The project is not assigned to this user."); } else Require(draft.ProjectId is null, "PROJECT_SCOPE", "This record kind is not project-scoped."); if (fields.TryGetValue("relatedProjectId", out var related) && related.Length > 0) { Require(_state.Records.Any(r => IsProject(r.Kind) && r.Id == related && !r.Deleted), "PROJECT_SCOPE", "The related project is unavailable."); Require(user.Role == "admin" || user.ProjectIds.Contains(related), "FORBIDDEN", "The related project is not assigned."); }
        foreach (var (key, value) in fields.Where(p => p.Key.EndsWith("AssetId", StringComparison.Ordinal) || p.Key == "assetId")) { if (value.Length == 0) continue; var linked = _state.Assets.SingleOrDefault(a => a.Id == value); Require(linked is not null && linked.ProjectId == draft.ProjectId, "PROJECT_SCOPE", "The asset does not belong to the record project."); AssetAccess(user, linked!.ProjectId); }
        ValidateAssetFields(fields); var next = Clone(); var record = new WorkRecord(old?.Id ?? Guid.NewGuid().ToString("N"), draft.Kind, draft.ProjectId, old?.OwnerId ?? user.Id, (old?.Revision ?? 0) + 1, false, fields); if (old is null) next.Records.Add(record); else next.Records[next.Records.FindIndex(r => r.Id == record.Id)] = record; Commit(next, ct); return Copy(record);
    }, ct);
    public async Task DeleteAsync(Identity actor, string kind, string id, long expectedRevision, bool confirmed, CancellationToken ct = default) { await Locked(() => { var user = Actor(actor); Schema(kind); Require(confirmed, "CONFIRMATION", "Confirm logical deletion."); var old = _state.Records.SingleOrDefault(r => r.Id == id && r.Kind == kind); Require(old is not null && !old.Deleted, "NOT_FOUND", "Record not found."); Writable(user, old!); if (kind == "file-folders") Require(!_state.Records.Any(r => !r.Deleted && r.ProjectId == old!.ProjectId && (r.Kind == "files" && r.Fields.GetValueOrDefault("folderId") == id || r.Kind == "file-folders" && r.Fields.GetValueOrDefault("parentId") == id)), "FOLDER_NOT_EMPTY", "Move or trash child files and folders before deleting this folder."); if (IsProject(kind)) Admin(user); Require(old!.Revision == expectedRevision, "REVISION", "The record has changed."); var next = Clone(); next.Records[next.Records.FindIndex(r => r.Id == id)] = old with { Deleted = true, Revision = old.Revision + 1 }; Commit(next, ct); return true; }, ct); }
    public Task<AppLayout> LoadAsync(CancellationToken ct = default) => Locked(() => JsonSerializer.Deserialize<AppLayout>(JsonSerializer.Serialize(_state.Layout, Json), Json)!, ct);
    public async Task SaveAsync(AppLayout layout, CancellationToken ct = default) { ValidateLayout(layout); await Locked(() => { var next = Clone(); next.Layout = JsonSerializer.Deserialize<AppLayout>(JsonSerializer.Serialize(layout, Json), Json)!; Commit(next, ct); return true; }, ct); }
    public async Task AuthorizeDocumentAsync(Identity actor, DocumentContext context, bool write, CancellationToken ct = default) { await Locked(() => { var user = Actor(actor); Require(context.UserId == user.Id, "UNAUTHENTICATED", "Document user does not match the authenticated session."); Require(context.ProjectId is not null, "PROJECT_SCOPE", "Select an authorized project."); var project = _state.Records.SingleOrDefault(r => IsProject(r.Kind) && r.Id == context.ProjectId && !r.Deleted); Require(project is not null && Readable(user, project), "FORBIDDEN", "The document project is unavailable."); if (write) Require(user.Role is "admin" or "editor", "FORBIDDEN", "This user cannot generate or change report artifacts."); return true; }, ct); }
    public void Dispose() { _disposed = true;/* Outstanding owned operations finish under their lease; no unowned process is touched. */}
    sealed class State { public int SchemaVersion { get; set; } = 1; public long Revision { get; set; } public List<StoredUser> Users { get; set; } = []; public List<WorkRecord> Records { get; set; } = []; public List<StoredAsset> Assets { get; set; } = []; public AppLayout Layout { get; set; } = new(); }
    sealed class StoredUser { public string Id { get; set; } = ""; public string DisplayName { get; set; } = ""; public string Role { get; set; } = "viewer"; public string Position { get; set; } = ""; public string[] ProjectIds { get; set; } = []; public bool Disabled { get; set; } public string Salt { get; set; } = ""; public string PasswordHash { get; set; } = ""; public int Iterations { get; set; } = 210000; }
    sealed class StoredAsset { public string Id { get; set; } = ""; public string ProjectId { get; set; } = ""; public string OwnerId { get; set; } = ""; public string Sha256 { get; set; } = ""; public string OriginalName { get; set; } = ""; public long Size { get; set; } public string MediaType { get; set; } = "application/octet-stream"; }
}
